	const createSalesInvoice = async (invoiceData) => {
		const idempotencyKey = invoiceData?.idempotencyKey || generateId("IDEMP");
		try {
			const res = await apiRequest("/api/invoices/sales", {
				method: "POST",
				body: invoiceData,
				idempotencyKey
			});
			await loadRoleScopedData();
			return {
				success: true,
				invoice: res.invoice
			};
		} catch (err) {
			if (isNetworkFailure(err) && currentUser) {
				if (!data.settings?.allowNegativeStock && invoiceData.status !== "draft" && invoiceData.warehouseId) for (const item of invoiceData.items || []) {
					const prod = data.products.find((p) => p.id === item.productId);
					const avail = Number(prod?.stockPerWarehouse?.[invoiceData.warehouseId] || 0);
					const needed = Number(item.quantity || 0) * Number(item.unitFactor || 1);
					if (needed > avail) return {
						success: false,
						error: tr(`الرصيد المحلي المتاح للصنف (${item.productName}) في المخزن المحدد هو (${avail}) فقط ولا يكفي للكمية المطلوبة (${needed}).`, `Available local stock for (${item.productName}) in selected warehouse is only (${avail}), insufficient for requested (${needed}).`)
					};
				}
				const localId = generateId("INV-LOC");
				const op = await queueOfflineOp({
					operationType: "create_sales_invoice",
					entityType: "invoice",
					localId,
					summaryAr: `فاتورة مبيعات محلية (${invoiceData.customerName || "عميل"}) بمبلغ ${invoiceData.grandTotal || 0} ج.م`,
					payload: {
						...invoiceData,
						localId
					}
				});
				const cust = data.customers.find((c) => c.id === invoiceData.customerId);
				return {
					success: true,
					invoice: {
						id: localId,
						invoiceNumber: `LOC-INV-${op.operationId.slice(-5)}`,
						type: "sales",
						status: invoiceData.status === "draft" ? "draft" : "confirmed",
						date: invoiceData.date || op.createdAt.slice(0, 10),
						customerId: invoiceData.customerId,
						customerName: invoiceData.customerName || cust?.name,
						warehouseId: invoiceData.warehouseId,
						warehouseName: invoiceData.warehouseName || "",
						items: invoiceData.items || [],
						subtotal: invoiceData.subtotal || 0,
						discountTotal: invoiceData.discountTotal || 0,
						taxTotal: invoiceData.taxTotal || 0,
						grandTotal: invoiceData.grandTotal || 0,
						paidAmount: invoiceData.paidAmount || 0,
						remainingAmount: invoiceData.remainingAmount || 0,
						paymentType: invoiceData.paymentType || "cash",
						paymentMethod: invoiceData.paymentMethod || "cash",
						cashboxId: invoiceData.cashboxId,
						notes: invoiceData.notes,
						createdBy: currentUser.id,
						createdAt: op.createdAt,
						payments: [],
						localId,
						operationId: op.operationId,
						syncStatus: "pending"
					},
					queuedOffline: true
				};
			}
			return {
				success: false,
				error: err?.message ? tr(err.message) : tr("تعذر إنشاء فاتورة المبيعات", "Could not create sales invoice")
			};
		}
	};
