	const updateServerSettings = async (newSettings, options = {}) => {
		const prevProfiles = (data.serverSettings || getEmptyClientDatabaseState().serverSettings).profiles || getStoredConnectionProfiles();
		const nextProfiles = newSettings.profiles ? {
			...prevProfiles,
			...newSettings.profiles,
			localNetwork: {
				...prevProfiles.localNetwork,
				...newSettings.profiles.localNetwork || {}
			},
			freeRemote: {
				...prevProfiles.freeRemote,
				...newSettings.profiles.freeRemote || {}
			},
			proRemote: {
				...prevProfiles.proRemote,
				...newSettings.profiles.proRemote || {}
			},
			cloudVps: {
				...prevProfiles.cloudVps,
				...newSettings.profiles.cloudVps || {}
			}
		} : prevProfiles;
		const canPersistServer = options.persistToServer !== false && isAuthenticated && Boolean(currentUser && (currentUser.role === "admin" || currentUser.permissions?.canManageSettings));
		let persistedConnectionConfig = nextProfiles;
		if (canPersistServer) try {
			const res = await apiRequest("/api/admin/settings", {
				method: "PUT",
				body: { extraSettings: {
					...data.settings?.extraSettings || {},
					connectionConfig: nextProfiles
				} }
			});
			if (res.settings?.extraSettings?.connectionConfig) persistedConnectionConfig = res.settings.extraSettings.connectionConfig;
		} catch (err) {
			return {
				success: false,
				error: err?.message ? tr(err.message) : tr("تعذر حفظ إعدادات الاتصال في السيرفر المركزي", "Could not save connection settings on central server")
			};
		}
		saveStoredConnectionProfiles(persistedConnectionConfig);
		if (options.applyToCurrentDevice === true) setConfiguredApiBaseUrl(options.targetDeviceUrl !== void 0 ? options.targetDeviceUrl : newSettings.apiBaseUrl ?? "");
		else if (options.applyToCurrentDevice === void 0 && newSettings.apiBaseUrl !== void 0) setConfiguredApiBaseUrl(newSettings.apiBaseUrl);
		setData((prev) => {
			const mergedExtra = {
				...prev.settings?.extraSettings || {},
				connectionConfig: persistedConnectionConfig
			};
			return {
				...prev,
				settings: {
					...prev.settings,
					extraSettings: mergedExtra
				},
				serverSettings: {
					...prev.serverSettings,
					...newSettings,
					profiles: persistedConnectionConfig
				}
			};
		});
		return { success: true };
	};
